--region handler
---入口点击回调
function ActivityJapaneseStoryNode:EntryOnClickHandler()
    if isNull(self._activityDojo) then
        return
    end
    if not self.isUnlock then
        local vo = self._activityDojo.unlock[1]
        local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
        GameUtils.Toast(err)
        return
    end
    xRecord.record('6-005', string.format('enter_activity_page_%d', checkInt(self._activityDojo.id)))
    JapaneseStoryUtils.Entry({ {id = Constants.UITypeIds.UIActivityMainDialog} }, {activityDojo = self._activityDojo, random = true})
end
--endregion handler

--region public
---刷新自身
---@param activityDojo ActivityDojo
function ActivityJapaneseStoryNode:Refresh(activityDojo)
    self._activityDojo = activityDojo
    if isNull(self._activityDojo) then return end

    local vo = checkTable(self._activityDojo.unlock)[1]
    if vo then
        self.isUnlock = GameUtils.IsUnlockedSingle(vo.targetType, vo.targetNum, vo.targetId)
    else
        self.isUnlock = true
    end

    self:RefreshUI()
end
--endregion public

--region private
---刷新UI
function ActivityJapaneseStoryNode:RefreshUI()
    self:RefreshActivityTime()
    self:RefreshStateGroup()
    self:RefreshTitle()
    self:RefreshEndTime()
    self:RefreshButton()
end

---刷新活动时间
function ActivityJapaneseStoryNode:RefreshActivityTime()
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self._activityDojo.startTime, self._activityDojo.endTime))
end

---刷新活动详情
function ActivityJapaneseStoryNode:RefreshStateGroup()
    CfUtils.FillText(self.Text, self._activityDojo.detail)
end

---刷新标题
function ActivityJapaneseStoryNode:RefreshTitle()
    local titleImgUrl = checkString(self._activityDojo.titleImage)
    if string.len(titleImgUrl) > 0 then
        CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
    end
end

---刷新结束时间
function ActivityJapaneseStoryNode:RefreshEndTime()
    CfUtils.FillText(self.TextTime2, ActivityUtils.ConvertActivityCloseTime(self._activityDojo.closeTime))

    if not self.isUnlock then
        local vo = self._activityDojo.unlock[1]
        local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
        CfUtils.FillText(self.TextLockDesc, err)
    end
    CfUtils.SetActive(self.ImgBg, self.isUnlock)
    CfUtils.SetActive(self.ImgLockBg, not self.isUnlock)
end

---刷新按钮
function ActivityJapaneseStoryNode:RefreshButton()
    local redPoint = self.BtnEntryGroup:Find("RedPoint")
    if isNull(redPoint) then return end
    
    CfUtils.SetActive(redPoint,  checkNumber(self._activityDojo.redDotHint) == 0)
end
